	// The state as one of this machine: each record saved at an earlier revision
	// of its schema holds the defaults of the fields added since.
	grown, err := sce.UpgradeSavedState(saved, &StaticUnionSavedShape)
	if err != nil {
		return nil, err
	}
	history, err := sce.RestoreHistory[StaticUnionState, StaticUnionEvent](policy, grown, StaticUnionHistories)
	if err != nil {
		return nil, err
	}
	raw1, err := grown.Variable("built")
	if err != nil {
		return nil, err
	}
	read1, err := StaticUnionUnionShapeUnionFromSaved(raw1, "built")
