// StaticUnionRestore is StaticUnionRestoreAt at the host's wall
// clock now.
func StaticUnionRestore(policy *StaticUnionPolicy, saved *sce.SavedState, clock sce.SceClock) (*sce.Engine[StaticUnionState, StaticUnionEvent], error) {
	return StaticUnionRestoreAt(policy, saved, clock, sce.SavedWallClockMs())
}

