// NewStaticUnionPolicy creates a new policy with default values.
func NewStaticUnionPolicy() StaticUnionPolicy {
	var vBuilt StaticUnionUnionShapeUnion = StaticUnionUnionShapeUnionRect(StaticUnionRectRecord{width: 1, height: 2})
	var vKept optional.Of[StaticUnionUnionShapeUnion] = optional.None[StaticUnionUnionShapeUnion]()
	var vLastKind StaticUnionKindEnum = StaticUnionKindEnumDot
	var vRadius uint16 = 0
	var vWidth uint16 = 0
	var vHeight uint16 = 0
	var vLabels uint32 = 0
	var vPoints uint32 = 0
	var vDots uint32 = 0
	var vManyRadius uint16 = 0
	var vManyWidth uint16 = 0
	var vManyShapes uint32 = 0
	var vMaybeWidth uint16 = 0
	var vRefusals uint32 = 0
	var vLifted optional.Of[StaticUnionUnionShapeUnion] = optional.None[StaticUnionUnionShapeUnion]()
	var vLiftWhy optional.Of[StaticUnionLiftRefusalRecord] = optional.None[StaticUnionLiftRefusalRecord]()
	var vPicked StaticUnionUnionShapeUnion = StaticUnionUnionShapeUnionDot()
	var vPickedMaybe optional.Of[StaticUnionUnionShapeUnion] = optional.None[StaticUnionUnionShapeUnion]()
	var vPicks uint32 = 0
	var vPickedWidth uint16 = 0
	var vHeld optional.Of[StaticUnionHeldRecord] = optional.None[StaticUnionHeldRecord]()
	var vHeldWhy optional.Of[StaticUnionLiftRefusalRecord] = optional.None[StaticUnionLiftRefusalRecord]()
	var vHeldWidth uint16 = 0
	var vBoard StaticUnionBoardRecord = StaticUnionBoardRecord{title: "desk", count: 2, note: optional.None[string](), shapes: []StaticUnionUnionShapeUnion{}, pinned: optional.None[StaticUnionUnionShapeUnion]()}
	var vBoardWhy optional.Of[StaticUnionLiftRefusalRecord] = optional.None[StaticUnionLiftRefusalRecord]()
	var vBoardShapes uint32 = 0
	var vBoards uint32 = 0
	return StaticUnionPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vBuilt: vBuilt,
		vKept: vKept,
		vLastKind: vLastKind,
		vRadius: vRadius,
		vWidth: vWidth,
		vHeight: vHeight,
		vLabels: vLabels,
		vPoints: vPoints,
		vDots: vDots,
		vManyRadius: vManyRadius,
		vManyWidth: vManyWidth,
		vManyShapes: vManyShapes,
		vMaybeWidth: vMaybeWidth,
		vRefusals: vRefusals,
		vLifted: vLifted,
		vLiftWhy: vLiftWhy,
		vPicked: vPicked,
		vPickedMaybe: vPickedMaybe,
		vPicks: vPicks,
		vPickedWidth: vPickedWidth,
		vHeld: vHeld,
		vHeldWhy: vHeldWhy,
		vHeldWidth: vHeldWidth,
		vBoard: vBoard,
		vBoardWhy: vBoardWhy,
		vBoardShapes: vBoardShapes,
		vBoards: vBoards,
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticUnionPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

